const sha256 = source => createHash('sha256').update(source).digest('hex')
function exactFile(path, hashes) {
  if (!Object.hasOwn(hashes, path)) return false
  try { return sha256(readFileSync(new URL('../' + path, import.meta.url))) === hashes[path] } catch { return false }
}
export const regionalCatalogueAllowsFileChange = path => exactFile(path, REGIONAL_CATALOGUE_HASHES)
export const regionalCatalogueAllowsNewFile = path => exactFile(path, REGIONAL_CATALOGUE_NEW_HASHES)

// Undo only the sealed, literal reviewed hunks; never discard a selector,
// function or file wholesale. A changed byte or duplicated hunk fails closed.
export function regionalCataloguePriorSource(path, source) {
  if (!Object.hasOwn(priorHashes, path)) return source
  if (sha256(source) === priorHashes[path]) return source
  if (sha256(source) !== REGIONAL_CATALOGUE_HASHES[path]) throw Error('Unreviewed regional source delta: ' + path)
  let previous = source
  for (const { before, after } of sourceEdits[path]) {
    if (!after || previous.split(after).length !== 2) throw Error('Ambiguous regional source delta: ' + path)
    previous = previous.replace(after, () => before)
  }
  if (sha256(previous) !== priorHashes[path]) throw Error('Regional source must restore every prior byte: ' + path)
  return previous
}
